import{_ as t,o as s,c as i,a3 as a}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse(`{"title":"Outil de création (packer) pour les paquets de widgets et d'outils","description":"Vérification des paquets pour « HA Grafik Visual Studio » et création de fichiers au format .wg ou .tp.","frontmatter":{"title":"Outil de création (packer) pour les paquets de widgets et d'outils","description":"Vérification des paquets pour « HA Grafik Visual Studio » et création de fichiers au format .wg ou .tp."},"headers":[],"relativePath":"fr/projects/grafik-visual-studio/packer.md","filePath":"fr/projects/grafik-visual-studio/packer.md","lastUpdated":1793127012000}`),r={name:"fr/projects/grafik-visual-studio/packer.md"};function n(o,e,l,d,u,c){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="packer-fur-widget-und-tool-pakete" tabindex="-1">Outil de création (packer) pour les paquets de widgets et d&#39;outils <a class="header-anchor" href="#packer-fur-widget-und-tool-pakete" aria-label="Permalink to &quot;Outil de création (packer) pour les paquets de widgets et d&#39;outils {#packer-fur-widget-und-tool-pakete}&quot;">​</a></h1><p>Les paquets et outils complémentaires sont proposés de manière centralisée sur <a href="https://visualstudio.ugso-software.de/?lang=de" target="_blank" rel="noreferrer">visualstudio.ugso-software.de</a>. Ce site open source contient des descriptions et des instructions ; le téléchargement s&#39;effectue via le catalogue de paquets.</p><p>L&#39;outil d&#39;empaquetage (« Packer ») crée, à partir d&#39;un dossier source, un paquet de widgets (<code>.wg</code>) ou un paquet d&#39;outils (<code>.tp</code>) pour HA Grafik Visual Studio. Ces deux fichiers sont des archives ZIP dotées d&#39;une extension spécifique. Avant l&#39;exportation, l&#39;outil vérifie le manifeste, la structure du paquet, les images SVG/PNG référencées ainsi que les contraintes définies par l&#39;interface des paquets de widgets (./widget-pakete) ou l&#39;interface des paquets d&#39;outils (./tool-pakete). Dans la version actuelle de l&#39;interface (0.1), les fichiers de paquet ne contiennent aucun code exécutable.</p><h2 id="paket-erstellen" tabindex="-1">Création d&#39;un paquet <a class="header-anchor" href="#paket-erstellen" aria-label="Permalink to &quot;Création d&#39;un paquet {#paket-erstellen}&quot;">​</a></h2><ol><li>Placez le fichier <code>manifest.json</code> dans le répertoire racine d&#39;un dossier source. Les images référencées doivent être placées conformément aux spécifications <code>icons/</code>. Les pages décrivant ces interfaces présentent les champs requis ainsi que des exemples.</li><li>Dans l&#39;outil d&#39;empaquetage, sélectionnez <strong>Paquet de widgets</strong> ou <strong>Paquet d&#39;outils</strong>, puis indiquez le dossier source et un dossier d&#39;exportation existant.</li><li>Vérifiez la liste des résultats ainsi que l&#39;identifiant du paquet, la version, la licence et le nom de destination. L&#39;option <strong>Exporter</strong> ne devient active que si le paquet est valide et si le nom de destination est disponible. L&#39;outil d&#39;empaquetage ne remplace aucun fichier existant.</li><li>Installez le fichier généré (<code>.wg</code> ou <code>.tp</code>) dans le Studio via <strong>Paramètres → Paquets de widgets</strong> ou <strong>Paramètres → Outils</strong>. Les anciennes extensions <code>.wg.zip</code> et <code>.tp.zip</code> restent utilisables.</li></ol><p>L&#39;outil d&#39;empaquetage effectue ses vérifications en appliquant les mêmes règles que l&#39;outil d&#39;importation intégré au Studio. Le paquet 0.3.0 prend en charge jusqu&#39;à 64 widgets par paquet ; Un paquet d&#39;outils contient exactement un outil dans l&#39;interface 0.1. Le Studio effectue en outre sa propre vérification pour chaque paquet importé.</p><h2 id="github-und-direkte-registrierung" tabindex="-1">GitHub et enregistrement direct <a class="header-anchor" href="#github-und-direkte-registrierung" aria-label="Permalink to &quot;GitHub et enregistrement direct {#github-und-direkte-registrierung}&quot;">​</a></h2><p>À partir de la version de test <strong>0.3.1</strong>, l&#39;outil de création de paquets (« Packer ») affiche en vert les paquets déjà enregistrés dont le contenu est identique, sous la mention <strong>Fichier enregistré</strong> ; cet état est conservé même après un redémarrage. Une nouvelle exportation reste désactivée. Si le contenu diffère, le mécanisme de vérification empêche toujours l&#39;écrasement du fichier. Le bouton large <strong>GitHub &amp; Catalogue…</strong> se situe juste en dessous de la liste de vérification.</p><p>Depuis la version <strong>Packer 0.3.0</strong>, l&#39;option <strong>GitHub &amp; Catalogue…</strong> permet d&#39;ouvrir un paquet <code>.wg</code> ou <code>.tp</code> exporté, en vue de sa vérification et de sa publication. La version de test <strong>0.3.1</strong> (proposée ci-dessous) intègre cette extension ainsi qu&#39;une correction concernant l&#39;affichage des fichiers enregistrés.</p><ol><li>Installez la <a href="https://cli.github.com/" target="_blank" rel="noreferrer">GitHub CLI</a> et connectez-vous via le terminal en utilisant <code>gh auth login</code>. Indiquez votre dépôt public et sélectionnez <strong>Charger les versions (Releases)</strong>.</li><li>Sélectionnez le tag de la version (release tag) et validez en choisissant <strong>Publier le paquet sur GitHub</strong>. Pour une nouvelle version, activez l&#39;option <strong>Créer une version (Release) pour un tag Git existant</strong> ; le tag doit déjà être présent sur GitHub. Les fichiers existants ne seront pas écrasés.</li><li>Le lien de téléchargement sera récupéré automatiquement. Alternativement, vous pouvez saisir directement un lien HTTPS (déjà publié) correspondant à une version fixe (<code>.wg</code> ou <code>.tp</code>), ce qui vous permet de sauter l&#39;étape GitHub.</li><li>Renseignez le lien vers la licence, la description, l&#39;adresse de contact interne ainsi que la version minimale requise du Studio. Indiquez si le paquet contient de nouvelles fonctionnalités en choisissant <strong>Non / Oui / Incertain</strong>. Si vous choisissez « Oui » ou « Incertain », une description est requise ; la version minimale peut, quant à elle, rester inconnue.</li><li>Consultez les <a href="https://visualstudio.ugso-software.de/privacy" target="_blank" rel="noreferrer">instructions d&#39;enregistrement</a>, confirmez l&#39;acceptation du traitement des données et des droits de distribution, puis sélectionnez <strong>Enregistrer dans le catalogue</strong>. Avant l&#39;envoi, l&#39;outil d&#39;empaquetage (Packer) affiche les destinataires et les informations saisies. Le paquet original est transmis pour une analyse automatique.</li><li>Une fois la soumission effectuée avec succès, copiez le lien de gestion privé. Le paquet apparaîtra dans le catalogue après une vérification manuelle et une validation. En cas de réponse réseau ambiguë, vérifiez d&#39;abord si la version a bien été enregistrée ; l&#39;outil ne relance pas automatiquement la soumission.</li></ol><p>L&#39;adresse de contact est transmise en interne au catalogue et, le cas échéant, à sa boîte de réception dédiée aux vérifications. Le nom, l&#39;adresse e-mail et le site web ne sont pas rendus publics. L&#39;outil d&#39;empaquetage conserve uniquement le dépôt et le lien vers la licence (par souci de commodité) ; il ne stocke ni l&#39;adresse de contact, ni les jetons GitHub, ni les consentements, ni les liens de gestion. Les opérations réseau s&#39;exécutent en arrière-plan. Les dossiers sources des widgets peuvent également contenir <code>LICENSE.txt</code> et <code>README.md</code>.</p><h2 id="programm-und-dateiendungen" tabindex="-1">Programme et extensions de fichiers <a class="header-anchor" href="#programm-und-dateiendungen" aria-label="Permalink to &quot;Programme et extensions de fichiers {#programm-und-dateiendungen}&quot;">​</a></h2><p>L&#39;interface Qt fonctionne sous Windows et Linux. Le bouton <strong>Enregistrer les extensions</strong> affiche d&#39;abord un aperçu ; après confirmation, il configure des icônes spécifiques ainsi que des entrées « Ouvrir avec » pour <code>.wg</code> et <code>.tp</code> pour l&#39;utilisateur actuel. L&#39;application par défaut existante n&#39;est pas modifiée. L&#39;outil d&#39;empaquetage permet d&#39;ouvrir un paquet existant pour vérification, sans l&#39;installer. Si le programme est déplacé, l&#39;enregistrement des types de fichiers doit être effectué à nouveau.</p><p>La version <strong>0.3.1</strong> est disponible en tant que version de test signée pour Windows et Linux dans le <a href="https://visualstudio.ugso-software.de/?kind=helper&amp;lang=de" target="_blank" rel="noreferrer">catalogue de paquets</a> :</p><table tabindex="0"><thead><tr><th>Système</th><th>Téléchargement</th><th>SHA-256</th></tr></thead><tbody><tr><td>Windows x86_64</td><td><a href="https://visualstudio.ugso-software.de/downloads/helpertools/HA-Grafik-Packer-0.3.1-windows-x86_64.zip" target="_blank" rel="noreferrer">Télécharger le ZIP</a></td><td><code>7047e6ee5bb2327cf80432d2c37e0f82516284c22c0d4910ff3d4d64950efd8a</code></td></tr><tr><td>Linux x86_64</td><td><a href="https://visualstudio.ugso-software.de/downloads/helpertools/HA-Grafik-Packer-0.3.1-linux-x86_64.tar.gz" target="_blank" rel="noreferrer">Télécharger le TAR.GZ</a></td><td><code>e094331c7281957764dee38a8a117d932a2589581117daf68f1e146b71fd9a19</code></td></tr></tbody></table><p>Décompressez entièrement l&#39;archive et lancez <code>HA-Grafik-Packer.exe</code> ou <code>HA-Grafik-Packer</code>. Le dossier <code>_internal</code> doit rester à côté ; il contient également les bibliothèques Qt, qui peuvent être remplacées séparément. Les deux versions (pour les différentes plateformes) ont été vérifiées au moyen de tests et d&#39;un autotest après décompression. Sous Linux, les bibliothèques système Qt sont requises pour EGL/OpenGL. Les textes de licence et diverses informations sont inclus dans l&#39;archive.</p><h2 id="download-prufen" tabindex="-1">Vérification du téléchargement <a class="header-anchor" href="#download-prufen" aria-label="Permalink to &quot;Vérification du téléchargement {#download-prufen}&quot;">​</a></h2><p>Pour la version 0.3.1, téléchargez <a href="https://visualstudio.ugso-software.de/downloads/helpertools/SHA256SUMS-0.3.1" target="_blank" rel="noreferrer">SHA256SUMS-0.3.1</a> et <a href="https://visualstudio.ugso-software.de/downloads/helpertools/SHA256SUMS-0.3.1.sig" target="_blank" rel="noreferrer">SHA256SUMS-0.3.1.sig</a>. Le <a href="https://raw.githubusercontent.com/rockbaer2007/ugso-opensource-docs/main/docs/public/keys/packer-allowed-signers" target="_blank" rel="noreferrer">fichier de confiance pour OpenSSH</a> et la <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/docs/packer-release.pub" target="_blank" rel="noreferrer">clé publique de publication</a> sont fournis séparément de la version publiée. L&#39;empreinte Ed25519 est <code>SHA256:W3iUvKedcI4FWS1kMoBrLlrAF2GbsB4sELphG0uITLE</code>. Les anciens fichiers de sommes de contrôle, dépourvus de numéro de version, correspondent à 0.2.0.</p><p>Vérifiez d&#39;abord la signature. Sous Linux, dans le dossier de téléchargement :</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packer-allowed-signers</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packer-release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ha-grafik-visual-studio-packer-release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SHA256SUMS-0.3.1.sig</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SHA256SUMS-0.3.1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha256sum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SHA256SUMS-0.3.1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Sous Windows, les mêmes paramètres de signature fonctionnent dans <code>cmd.exe</code> en utilisant la redirection d&#39;entrée indiquée. Comparez ensuite <code>certutil -hashfile DATEINAME SHA256</code> avec la valeur contenue dans <code>SHA256SUMS-0.3.1</code>. Avant d&#39;effectuer la vérification, téléchargez la clé et le fichier de confiance depuis les sources indiquées par les liens ci-dessus. Le code source de l&#39;outil de compression demeure dans le dépôt de développement privé.</p>`,21)])])}const h=t(r,[["render",n]]);export{g as __pageData,h as default};
